// Decodes the packed Wend word list (src/data/wend-words.ts, generated by
// scripts/make-wend-dict.mjs) on first use. Decoding takes a few tens of ms,
// so it only happens when a Wend puzzle is actually solved.
import { WEND_WORDS_PACKED } from './wend-words.ts';
import type { WendDict } from '../solvers/wend.ts';

/** Decode the packed format: '\n'-separated rank blocks of front-coded words. */
export function decodeWendWords(packed: string): WendDict {
  const words: string[] = [];
  const ranks: number[] = [];
  const blocks = packed.split('\n');
  for (let r = 0; r < blocks.length; r++) {
    const b = blocks[r];
    let prev = '';
    let i = 0;
    while (i < b.length) {
      const k = b.charCodeAt(i++) - 48;
      let j = i;
      while (j < b.length && b.charCodeAt(j) >= 97) j++;
      const w = prev.slice(0, k) + b.slice(i, j);
      words.push(w.toUpperCase());
      ranks.push(r);
      prev = w;
      i = j;
    }
  }
  return { words, ranks };
}

let cached: WendDict | null = null;

/** The bundled dictionary (decoded once, then cached). */
export function wendDict(): WendDict {
  return (cached ??= decodeWendWords(WEND_WORDS_PACKED));
}
